def find_digit(k):
    """Find the digit at position k in the sequence."""

    def count_digits_in_range(start, end):
        """Count total digits from start to end inclusive."""
        if start > end:
            return 0

        result = 0

        # Count numbers with same digit length
        for length in range(len(str(start)), len(str(end)) + 1):
            if length == len(str(start)):
                start_count = start
                start_delta = 0
            else:
                start_count = 10 ** (length - 1)
                start_delta = 0

            if length == len(str(end)):
                end_count = end
                end_delta = 0
            else:
                end_count = 10 ** length - 1
                end_delta = 0

            if start_count <= end_count:
                count = min(end_count, end_count) - max(start_count, start_count) + 1
                result += count * length

        return result

    # Find which block contains position k
    block_length = 0
    block_num = 1

    while True:
        block_length += block_num  # Block 'i' has i digits total
        if k <= block_length:
            break
        k -= block_length
        block_num += 1

    # Now k is the position within block 'block_num'
    # Find which number within 1..block_num contains digit k

    num_len = 1
    start_num = 1
    count = 0

    while count + (block_num - start_num + 1) * num_len < k:
        end_num = min(block_num, 10 ** num_len - 1)
        if end_num < start_num:
            break

        total = count + (end_num - start_num + 1) * num_len
        if total >= k:
            break

        # Add all numbers with num_len digits
        count += (end_num - start_num + 1)
        start_num = end_num + 1
        num_len += 1

        # If we exceed block_num, break
        if start_num > block_num:
            break

    # Find the exact number and digit
    remaining = k - count

    # Now trying to find within the remaining numbers
    offset = 0
    for num in range(start_num, block_num + 1):
        s_num = str(num)
        if remaining <= len(s_num):
            return int(s_num[remaining - 1])
        remaining -= len(s_num)

    return str(s_num[-1])

def solution(input_str):
    """
    Calculates the maximum number of chessmen that can be placed on an n×m chessboard
    such that each pair has Manhattan distance exactly 3.
    """
    n, m = map(int, input_str.strip().split())

    # For very small boards:
    if n <= m:
        # Check if both dimensions are small enough that no distance 3 pairs exist
        if n <= 2 and m <= 2:
            return "0"

        # Special small cases
        if m == 3 and n == 2:
            return "0"

        if m == 2 and n == 3:
            return "0"

        if m == 2 and n >= 4:
            return str((n - 1) // 2 * 2)

        if m == 3 and n >= 4:
            # For small width 3, limited pairs
            return if_small_n_3(n, 3)

    else:
        if n == 2 and m <= 2:
            return "0"

        if n == 2 and m >= 4:
            return str((m - 1) // 2 * 2)

        if n == 3 and m <= 3:
            return if_small_n_3(3, m)

    # General case: large boards can almost always tile optimally
    total = n * m
    if total % 2 == 0:
        return str(total)
    else:
        return str(total - 1)

def if_small_n_3(n, m):
    """Handle 3 × m and n × 3 cases."""
    # For 3×3: 9 cells, but can only place 8
    if n == 3 and m == 3:
        return "8"

    # For 3×2 and 2×3: 0
    if m == 2 or n == 2:
        return "0"

    # For 3×m where m >= 4
    return str(2 * (m - 1)) if m >= 4 else str(n * m - 1)


