from collections import defaultdict

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = defaultdict(list)
    edges_added = 0

    for i in range(1, len(lines)):
        if i < m + 1:
            u, v = map(int, lines[i].split())
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            count = 0
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            component_sizes.append(count)

    if not component_sizes:
        component_sizes = [0]

    # Generate lucky numbers up to n
    lucky_numbers = []

    def generate_lucky(current):
        if current > n:
            return
        if current != 0:  # 0 is not a positive lucky number
            lucky_numbers.append(current)
        if current > n:
            return
        generate_lucky(current * 10 + 4)
        generate_lucky(current * 10 + 7)

    generate_lucky(0)
    # Also add single digit 4 and 7
    if 4 <= n:
        lucky_numbers.append(4)
    if 7 <= n:
        lucky_numbers.append(7)

    lucky_set = set(lucky_numbers)
    lucky_sum = sum(lucky_numbers)

    # Sort component sizes and use DP
    component_sizes.sort()

    # dp[s] = minimum number of components to achieve sum s
    # Limit to n+1 since we can only sum to n
    max_sum = n
    dp = [float('inf')] * (max_sum + 1)
    dp[0] = 0

    # Process each component size
    for size in component_sizes:
        # Go backwards to avoid using same component multiple times
        for s in range(size - 1, -1, -1):
            if dp[s] != float('inf'):
                new_sum = s + size
                if new_sum <= max_sum:
                    dp[new_sum] = min(dp[new_sum], dp[s] + 1)

    # Find minimum roads needed
    min_roads = -1

    for lucky in lucky_numbers:
        if lucky <= max_sum and dp[lucky] != float('inf'):
            roads_needed = dp[lucky] - 1
            roads_needed = max(0, roads_needed)
            if min_roads == -1 or roads_needed < min_roads:
                min_roads = roads_needed

    if min_roads == -1:
        return "-1\n"
    else:
        return f"{min_roads}\n"

