        parts = lines[2 + i].split()
        u, v = int(parts[0]), int(parts[1])
        w = int(parts[2])
        edge_idx = i + 1
        edges.append({'idx': edge_idx, 'u': u, 'v': v, 'w': w})
        adj[u].append((v, edge_idx))
        adj[v].append((u, edge_idx))

    def can_reach(start, exclusions):
        visited = [False] * (n + 1)
        visited[start] = True
        q = deque([start])
        while q:
            u = q.popleft()
            if u == t:
                return True
            for v, idx in adj[u]:
                if idx not in exclusions and not visited[v]:
                    visited[v] = True
                    q.append(v)
        return visited[t]

    if not can_reach(s, set()):
        return "0\n0\n"

    best_cost = float('inf')
    best_edges = []

    # Try single edges
    for edge in edges:
        if can_reach(s, {edge['idx']}):
            if edge['w'] < best_cost:
                best_cost = edge['w']
                best_edges = [edge['idx']]

    # Try pairs of edges
    for i in range(m):
        for j in range(i + 1, m):
            e1, e2 = edges[i], edges[j]
            if can_reach(s, {e1['idx'], e2['idx']}):
                total = e1['w'] + e2['w']
                if total < best_cost:
                    best_cost = total
                    best_edges = [e1['idx'], e2['idx']]

    if best_cost == float('inf'):
        return "-1"

    return f"{best_cost}\n{len(best_edges)}\n{' '.join(str(x) for x in best_edges)}"


