MOD = 10**9 + 7

class Result:
    def __init__(self, length, value):
        self.length = length
        self.value = value

    def concat(self, other):
        total_length = self.length + other.length
        power_of_10 = pow(10, other.length, MOD)
        new_value = (self.value * power_of_10 + other.value) % MOD
        return Result(total_length, new_value)

def count_digits(n):
    return len(str(n))

def construct_for_range(l, r, mod):
    """Construct the result for concatenation of numbers from l to r"""
    result = Result(count_digits(l), l % mod, None)

    for i in range(l + 1, r + 1):
        d_count = count_digits(i)
        power = pow(10, d_count, mod)
        result = Result(result.length + d_count, (result.value * power + i) % mod, result.value * power)

    return result

def handle_range(t1, t2, mod):
    """Handle the range concatenation l-r"""
    return Result(t1.length + t2.length, (t1.value * pow(10, t2.length, mod) + t2.value) % mod)

