class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, cap, cost=0, edge_idx=-1):
        self.graph[u].append([v, cap, cost, edge_idx])
        self.graph[v].append([u, 0, -cost, -1 - len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, cost, edge_idx in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, cost, edge_idx = self.graph[u][i]
            if self.level[v] != self.level[u] + 1 or cap <= 0:
                continue
            pushed = self.dfs(v, t, min(flow, cap), ptr)
            if pushed > 0:
                self.graph[u][i][1] -= pushed  # cap - flow
                self.graph[v][len(self.graph[v]) - 1][1] += pushed
                return pushed
        return 0

    def max_flow(self, s, t):
        max_flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                max_flow += pushed
        return max_flow

