def bfs_find_path(start, end, adj, exclude_vertices, used_edges):
    """Find a simple path from start to end avoiding exclude_vertices and used_edges"""
    from collections import deque

    if start == end:
        return [start, end]

    visited = {start}
    q = deque([(start, [start])])

    while q:
        node, path = q.popleft()

        for neighbor in adj[node]:
            if neighbor in visited:
                continue
            if neighbor in exclude_vertices:
                continue

            edge_key = (min(node, neighbor), max(node, neighbor))
            if edge_key in used_edges:
                continue

            new_visited = visited | {neighbor}
            new_path = path + [neighbor]

            if neighbor == end:
                return new_path

            q.append((neighbor, new_path))

    return None


