            matrix.append(row)

        ops = get_line()

        # Count shifts
        row_shift = 0  # Positive = down
        col_shift = 0  # Positive = right

        for op in ops:
            if op == 'R':
                col_shift += 1
            elif op == 'L':
                col_shift -= 1
            elif op == 'D':
                row_shift += 1
            elif op == 'U':
                row_shift -= 1

        row_shift %= n
        col_shift %= n

        # Count inverses
        has_inv_row = ops.count('I') % 2 == 1
        has_inv_col = ops.count('C') % 2 == 1

        # First apply column inverse (C operations affect columns)
        if has_inv_col:
            for c in range(n):
                # Inverse the column c
                col = [matrix[r][c] for r in range(n)]
                inv_col = [required[0] for required in enumerate(col, 1)]
                for r in range(n):
                    matrix[r][c] = inv_col[r]

        # Apply shifts to get base matrix
        shifted = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                orig_i = (i - row_shift + n) % n
                orig_j = (j - col_shift + n) % n
                shifted[i][j] = matrix[orig_i][orig_j]

        # Apply row inverse if needed
        if has_inv_row:
            for i in range(n):
                row = shifted[i]
                inv_row = [req[0] for req in enumerate(row, 1)]
                shifted[i] = inv_row

        # Build result
        result_lines = []
        for i in range(n):
            result_lines.append(' '.join(map(str, shifted[i])))
        results.append('\n'.join(result_lines))

    return '\n\n'.join(results)

