import math
from typing import List

MOD = 10**9 + 7

def get_square_free_part(n: int) -> int:
    """Extract the square-free part of n."""
    result = 1
    d = 2
    temp = n
    while d * d <= temp:
        if temp % (d * d) == 0:
            temp //= (d * d)
        elif temp % d == 0:
            result *= d
            temp //= d
        d += 1 if d == 2 else 2
    if temp > 1:
        result *= temp
    return result

def mod_pow(base: int, exp: int, mod: int) -> int:
    """Compute base^exp mod mod."""
    result = 1
    base %= mod
    while exp > 0:
        if exp % 2 == 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp //= 2
    return result

def precompute_factorials(n: int) -> List[int]:
    """Precompute factorials and inverse factorials modulo MOD."""
    fact = [1] * (n + 1)
    inv = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i - 1] * i) % MOD
    inv[n] = mod_pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv[i] = (inv[i + 1] * (i + 1)) % MOD
    return fact, inv

def nCr_mod(n: int, r: int, fact: List[int], inv: List[int]) -> int:
    """Compute nCr modulo MOD."""
    if r < 0 or r > n:
        return 0
    return fact[n] * inv[r] % MOD * inv[n - r] % MOD

