        xi_min = float('-inf')
        xi_max = float('inf')

        if vix == 0:
            if not (x1 < rix < x2):
                return '-1'
            else:
                xi_min = xi_max = 0  # Always inside for all t
        else:
            t1_x = (x1 - rix) / vix
            t2_x = (x2 - rix) / vix

            if vix > 0:
                xi_min = t1_x
                xi_max = t2_x
            else:
                xi_min = t2_x
                xi_max = t1_x

        # Calculate valid time interval for y-coordinate: y1 < riy + viy*t < y2
        yi_min = float('-inf')
        yi_max = float('inf')

        if viy == 0:
            if not (y1 < riy < y2):
                return '-1'
            else:
                yi_min = yi_max = 0
        else:
            t1_y = (y1 - riy) / viy
            t2_y = (y2 - riy) / viy

            if viy > 0:
                yi_min = t1_y
                yi_max = t2_y
            else:
                yi_min = t2_y
                yi_max = t1_y

        # Intersection of x and y intervals for this mouse
        mouse_min = max(xi_min, yi_min)
        mouse_max = min(xi_max, yi_max)

