        # Check cycle
        adj = defaultdict(set)
        for src in needed:
            adj[src] = needed[src].copy()

        visited = set()
        rec_stack = set()
        in_cycle = False

        def dfs(node):
            nonlocal in_cycle
            visited.add(node)
            rec_stack.add(node)
            for target in adj[node]:
                if target not in visited:
                    if dfs(target):
                        return True
                elif target in rec_stack:
                    in_cycle = True
                    return True
            rec_stack.remove(node)
            return False

        for char in needed:
            if char not in visited:
                dfs(char)

        # Check impossible case: if any position has A[i] -> B[i] and B[i] -> something that 
        # conflicts with original A[i]
        if in_cycle:
            # Find all characters involved in any cycle
            result_chars = set()
            for src in needed:
                dst = needed[src]
                for d in dst:
                    if src in d or (d, src) in adj and src in needed[d]:
                        result_chars.add(src)
                        result_chars.add(d)

            # If it's an impossible cycle
            ans = -1
        else:
            # Count moves: each char that needs to become something is 1 edge
            # Plus merges reduce this
            ans = len([c for c in needed if needed[c]])

        results.append(str(ans) if ans != -1 else str(ans))

    return '\n'.join(results)

