    if n == 0:
        return '0\n'

    from collections import deque

    queue = deque([(n, 0)])
    visited = {n}

    while queue:
        curr, dist = queue.popleft()

        digits = set(str(curr))
        for d in digits:
            digit = int(d)
            if digit > 0:
                next_val = curr - digit
                if next_val == 0:
                    return f"{dist + 1}\n"
                if next_val not in visited:
                    visited.add(next_val)
                    queue.append((next_val, dist + 1))

    return '0\n'

