def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    edges = []
    for line in lines[1:]:
        if line.strip():
            parts = line.split()
            if len(parts) >= 2:
                a, b = int(parts[0]), int(parts[1])
                edges.append((min(a, b), max(a, b)))

    def crossing(a1, b1, a2, b2):
        """Check if two edges cross"""
        return (a1 < a2 < b1 < b2) or (a2 < a1 < b2 < b1)

    # For edge i: variable 2*i = outside, 2*i+1 = inside
    total_vars = 2 * m
    adj = [[] for _ in range(total_vars)]

    for i in range(m):
        for j in range(i + 1, m):
            a1, b1 = edges[i]
            a2, b2 = edges[j]
            if crossing(a1, b1, a2, b2):
                # Edge i crosses edge j
                # i inside => j outside
                adj[2*i + 1].append(2*j)
                # j inside => i outside
                adj[2*j + 1].append(2*i)
                # i outside => j inside
                adj[2*i].append(2*j + 1)
                # j outside => i inside
                adj[2*j].append(2*i + 1)

    # Tarjan's algorithm for SCC
    visited = [False] * total_vars
    ids = [-1] * total_vars
    low = [0] * total_vars
    on_stack = [False] * total_vars
    stack = []
    scc_id = [-1] * total_vars
    timer = 0
    scc_count = 0

    def dfs(u):
        nonlocal timer, scc_count
        visited[u] = True
        ids[u] = low[u] = timer
        timer += 1
        stack.append(u)
        on_stack[u] = True

        for v in adj[u]:
            if not visited[v]:
                dfs(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], ids[v])

        if ids[u] == low[u]:
            while stack:
                v = stack.pop()
                on_stack[v] = False
                scc_id[v] = scc_count - 1
                if v == u:
                    break
            scc_count += 1

    for i in range(total_vars):
        if not visited[i]:
            dfs(i)

    # Check consistency and build output
    result = ""
    for i in range(m):
        if scc_id[2*i] == scc_id[2*i + 1]:
            return "Impossible"
        # If outside SCC has higher id, it's the valid choice
        if scc_id[2*i] > scc_id[2*i + 1]:
            result += "o"
        else:
            result += "i"

    return result + "\n"

