        # Find valid range for b
        # Constraints: a <= b <= n
        #                c = 2ab - a^2 >= 1  => 2ab >= a^2 + 1 => b >= (a^2 + 1) / (2a)
        #                c = 2ab - a^2 <= m  => 2ab <= m + a^2 => b <= (m + a^2) / (2a)

        # Minimum b
        b_min = a  # since a <= b

        if 2 * a * a + 1 <= 2 * a * n:
            if a * a % (2 * a) == 0:
                b_min_check = a
            else:
                b_min_check = a * a // (2 * a) + 1
            b_min = max(b_min, b_min_check)

        # Actually simpler: b must satisfy a <= b <= n and c in [1, m]
        # c = 2ab - a^2

        valid_b_count = 0
        for b in range(a, n + 1):
            c = 2 * a * b - a * a
            if 1 <= c <= m:
                valid_b_count += 1

        if valid_b_count > 0:
            count += valid_b_count

    return str(count)


