from itertools import product

def solution(input_text):
    n, r = map(int, input_text.split())

    # Find all valid integer points (distance ≤ r from origin)
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                points.append((x, y))

    num_points = len(points)

    best_score = -1
    best_config = None

    def calc_score(towers):
        """Calculate sum of squared distances between all pairs of towers"""
        score = 0
        m = len(towers)
        for i in range(m):
            for j in range(i + 1, m):
                dx = towers[i][0] - towers[j][0]
                dy = towers[i][1] - towers[j][1]
                score += dx * dx + dy * dy
        return score

    # Explore all combinations with replacement (towers can be at same position)
    for combo in product(range(num_points), repeat=n):
        towers = [points[i] for i in combo]
        score = calc_score(towers)
        if score > best_score:
            best_score = score
            best_config = towers.copy()

    # Format output
    out_lines = [str(best_score)]
    for x, y in best_config:
        out_lines.append(f"{x} {y}")
    return '\n'.join(out_lines)
